// Minimal stdio MCP client: spawns the exact server OpenClaw registered.
import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';
const cfg = JSON.parse(readFileSync(process.env.OPENCLAW_CONFIG_PATH, 'utf8')).mcp.servers.gbrain;
const p = spawn(cfg.command, cfg.args, { cwd: '/tmp', env: { ...process.env, ...cfg.env }, stdio: ['pipe', 'pipe', 'inherit'] });
let buf = ''; const waiters = new Map(); let id = 0;
p.stdout.on('data', (d) => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0, i); buf = buf.slice(i + 1); if (!line.trim()) continue; try { const m = JSON.parse(line); if (m.id && waiters.has(m.id)) { waiters.get(m.id)(m); waiters.delete(m.id); } } catch {} } });
const call = (method, params) => new Promise((res) => { const n = ++id; waiters.set(n, res); p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: n, method, params }) + '\n'); });
const mode = process.argv[2];
const init = await call('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'install-check', version: '1' } });
console.log('server:', JSON.stringify(init.result?.serverInfo));
p.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
const tools = await call('tools/list', {});
console.log('tools:', tools.result?.tools.map((t) => t.name).join(', '));
const show = (r) => console.log(JSON.stringify(r.result ?? r.error).slice(0, 1500));
if (mode === 'recall') show(await call('tools/call', { name: 'recall', arguments: { entity: 'gbrain-install-check', _meta: { hot_memory: 'off' } } }));
if (mode === 'search') show(await call('tools/call', { name: 'search', arguments: { query: process.argv[3] } }));
if (mode === 'remember') show(await call('tools/call', { name: 'remember', arguments: JSON.parse(process.argv[3]) }));
if (mode === 'forget') show(await call('tools/call', { name: 'forget', arguments: JSON.parse(process.argv[3]) }));
p.kill(); process.exit(0);

